package com.acme.tracker.web;

import com.acme.tracker.dao.PersonDao;
import com.acme.tracker.model.Person;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class LoginServlet extends HttpServlet {

    private final PersonDao people = new PersonDao();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        req.getRequestDispatcher("/WEB-INF/jsp/login.jsp").forward(req, resp);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");
        Person user = people.authenticate(username, password);
        if (user == null) {
            req.setAttribute("error", "Invalid credentials");
            req.getRequestDispatcher("/WEB-INF/jsp/login.jsp").forward(req, resp);
            return;
        }
        req.getSession(true).setAttribute("user", user);
        resp.sendRedirect(req.getContextPath() + "/tasks");
    }
}
package com.acme.tracker.web;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.http.HttpSession;
import java.io.IOException;

public class LogoutServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        HttpSession session = req.getSession(false);
        if (session != null) {
            session.invalidate();
        }
        resp.sendRedirect(req.getContextPath() + "/login");
    }
}
package com.acme.tracker.web;

import com.acme.tracker.model.Person;

import javax.servlet.Filter;
import javax.servlet.FilterChain;
import javax.servlet.ServletException;
import javax.servlet.ServletRequest;
import javax.servlet.ServletResponse;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.http.HttpSession;
import java.io.IOException;

/**
 * Servlet filter applied to incoming requests (mapped to /* in web.xml).
 */
public class AuthFilter implements Filter {

    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest request = (HttpServletRequest) req;
        HttpServletResponse response = (HttpServletResponse) res;
        String path = request.getServletPath();
        String ctx = request.getContextPath();

        if (path.equals("/login") || path.startsWith("/api/") || path.endsWith(".css")) {
            chain.doFilter(req, res);
            return;
        }

        HttpSession session = request.getSession(false);
        Person user = session == null ? null : (Person) session.getAttribute("user");
        if (user == null) {
            response.sendRedirect(ctx + "/login");
            return;
        }

        if (path.equals("/tasks/action")) {
            String action = request.getParameter("action");
            if (("approve".equals(action) || "reject".equals(action)) && !user.getRole().canApprove()) {
                response.sendError(HttpServletResponse.SC_FORBIDDEN,
                        "Only managers or admins may approve or reject tasks");
                return;
            }
        }

        chain.doFilter(req, res);
    }

    @Override
    public void init(javax.servlet.FilterConfig filterConfig) {
    }

    @Override
    public void destroy() {
    }
}
package com.acme.tracker.web;

import com.acme.tracker.dao.PersonDao;
import com.acme.tracker.dao.ProjectDao;
import com.acme.tracker.model.Person;
import com.acme.tracker.model.Project;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Lists projects, creates new ones, and archives an existing one.
 */
public class ProjectServlet extends HttpServlet {

    private final ProjectDao projects = new ProjectDao();
    private final PersonDao people = new PersonDao();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        req.setAttribute("projects", projects.findAll());
        req.setAttribute("people", people.findAll());
        req.getRequestDispatcher("/WEB-INF/jsp/projects.jsp").forward(req, resp);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String action = req.getParameter("action");
        if ("archive".equals(action)) {
            projects.archive(Long.parseLong(req.getParameter("id")));
            resp.sendRedirect(req.getContextPath() + "/projects");
            return;
        }
        // create
        String name = req.getParameter("name");
        if (name == null || name.trim().isEmpty()) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Project name is required");
            return;
        }
        Person user = (Person) req.getSession().getAttribute("user");
        Project p = new Project();
        p.setName(name.trim());
        p.setDescription(req.getParameter("description"));
        p.setOwnerId(user.getId());
        projects.create(p);
        resp.sendRedirect(req.getContextPath() + "/projects");
    }
}

package com.acme.tracker.web;

import com.acme.tracker.dao.TaskDao;
import com.acme.tracker.model.Person;
import com.acme.tracker.model.Task;
import com.acme.tracker.model.TaskStatus;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Changes a task's status, and closes several tasks at once. Each action
 * checks the task's current status is the one it expects before writing the new
 * one.
 */
public class TaskActionServlet extends HttpServlet {

    private final TaskDao tasks = new TaskDao();

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String action = req.getParameter("action");

        if ("bulkClose".equals(action)) {
            handleBulkClose(req, resp);
            return;
        }

        long id = Long.parseLong(req.getParameter("id"));
        Task t = tasks.findById(id);
        if (t == null) {
            resp.sendError(HttpServletResponse.SC_NOT_FOUND, "No such task");
            return;
        }
        String current = t.getStatus();

        switch (action == null ? "" : action) {
            case "start":
                if (!guard(resp, current, TaskStatus.OPEN, action)) return;
                tasks.updateStatus(id, TaskStatus.IN_PROGRESS);
                break;
            case "submit":
                if (!guard(resp, current, TaskStatus.IN_PROGRESS, action)) return;
                tasks.updateStatus(id, TaskStatus.PENDING_APPROVAL);
                break;
            case "approve":
                if (!requireApprover(req, resp)) return;
                if (!guard(resp, current, TaskStatus.PENDING_APPROVAL, action)) return;
                tasks.updateStatus(id, TaskStatus.DONE);
                break;
            case "reject":
                if (!requireApprover(req, resp)) return;
                if (!guard(resp, current, TaskStatus.PENDING_APPROVAL, action)) return;
                tasks.updateStatus(id, TaskStatus.IN_PROGRESS);
                break;
            case "reopen":
                if (!guard(resp, current, TaskStatus.DONE, action)) return;
                tasks.updateStatus(id, TaskStatus.OPEN);
                break;
            default:
                resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Unknown action: " + action);
                return;
        }
        if (!resp.isCommitted()) {
            // Optional: return to the focused task detail page (used by the
            // detail view's transition buttons). Default stays the list.
            String target = "detail".equals(req.getParameter("return"))
                    ? "/tasks/form?id=" + id
                    : "/tasks";
            resp.sendRedirect(req.getContextPath() + target);
        }
    }

    private void handleBulkClose(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String[] raw = req.getParameterValues("ids");
        if (raw == null || raw.length == 0) {
            resp.sendRedirect(req.getContextPath() + "/tasks");
            return;
        }
        long[] ids = new long[raw.length];
        for (int i = 0; i < raw.length; i++) {
            ids[i] = Long.parseLong(raw[i]);
        }
        tasks.bulkClose(ids);
        resp.sendRedirect(req.getContextPath() + "/tasks");
    }

    /** Authorization check for the approve and reject actions. */
    private boolean requireApprover(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        Person user = (Person) req.getSession().getAttribute("user");
        if (user == null || !user.getRole().canApprove()) {
            resp.sendError(HttpServletResponse.SC_FORBIDDEN, "Approval requires a manager or admin");
            return false;
        }
        return true;
    }

    /** Refuse the change unless the task is already in the expected status. */
    private boolean guard(HttpServletResponse resp, String current, String expected, String action)
            throws IOException {
        if (!expected.equals(current)) {
            resp.sendError(HttpServletResponse.SC_CONFLICT,
                    "Cannot " + action + " a task in status " + current + " (expected " + expected + ")");
            return false;
        }
        return true;
    }
}
package com.acme.tracker.web;

import com.acme.tracker.dao.TaskDao;
import com.acme.tracker.model.Task;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;

/**
 * Serves the task list. With no filter params it shows every task; the
 * status and assignee params narrow it down.
 */
public class TaskListServlet extends HttpServlet {

    private final TaskDao tasks = new TaskDao();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String status = req.getParameter("status");
        String assigneeParam = req.getParameter("assignee");
        String sort = req.getParameter("sort");

        // Route everything through search — with null filters it returns all
        // tasks, so the chosen sort applies to the default list too. Default
        // (no sort param) is most-recently-updated first.
        Long assigneeId = (assigneeParam == null || assigneeParam.isEmpty()) ? null : Long.valueOf(assigneeParam);
        List<Task> result = tasks.search(status, assigneeId, sort);

        req.setAttribute("tasks", result);
        req.setAttribute("statusFilter", status);
        req.setAttribute("sortBy", (sort == null || sort.isEmpty()) ? "updated" : sort);
        req.getRequestDispatcher("/WEB-INF/jsp/tasks.jsp").forward(req, resp);
    }
}
package com.acme.tracker.web;

import com.acme.tracker.dao.TaskDao;
import com.acme.tracker.model.Task;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.List;

/**
 * GET /api/tasks[?status=DONE] returns a JSON read-back of task rows straight
 * from the DB, outside the UI path. JSON is hand-rolled (no Jackson) to keep
 * the dependency surface legacy-thin.
 */
public class ApiTaskServlet extends HttpServlet {

    private final TaskDao tasks = new TaskDao();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String status = req.getParameter("status");
        List<Task> rows = (status == null || status.isEmpty())
                ? tasks.findAll()
                : tasks.search(status, null, null);

        resp.setContentType("application/json");
        resp.setCharacterEncoding("UTF-8");
        PrintWriter out = resp.getWriter();
        out.append('[');
        for (int i = 0; i < rows.size(); i++) {
            Task t = rows.get(i);
            if (i > 0) out.append(',');
            out.append('{')
               .append("\"id\":").append(String.valueOf(t.getId())).append(',')
               .append("\"title\":\"").append(esc(t.getTitle())).append("\",")
               .append("\"status\":\"").append(esc(t.getStatus())).append("\",")
               .append("\"priority\":\"").append(esc(t.getPriority())).append("\",")
               .append("\"assigneeId\":").append(t.getAssigneeId() == null ? "null" : String.valueOf(t.getAssigneeId())).append(',')
               .append("\"projectId\":").append(String.valueOf(t.getProjectId())).append(',')
               .append("\"dueDate\":").append(t.getDueDate() == null ? "null" : "\"" + esc(t.getDueDate()) + "\"").append(',')
               .append("\"updatedAt\":\"").append(esc(t.getUpdatedAt())).append("\"")
               .append('}');
        }
        out.append(']');
        out.flush();
    }

    private static String esc(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
package com.acme.tracker.web;

import com.acme.tracker.dao.PersonDao;
import com.acme.tracker.dao.ProjectDao;
import com.acme.tracker.dao.TaskDao;
import com.acme.tracker.model.Task;
import com.acme.tracker.model.TaskStatus;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Creates and edits tasks. GET renders the form (blank for new, pre-filled
 * when ?id= is present); POST validates and persists.
 */
public class TaskFormServlet extends HttpServlet {

    private final TaskDao tasks = new TaskDao();
    private final ProjectDao projects = new ProjectDao();
    private final PersonDao people = new PersonDao();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String idParam = req.getParameter("id");
        if (idParam != null && !idParam.isEmpty()) {
            req.setAttribute("task", tasks.findById(Long.parseLong(idParam)));
        }
        req.setAttribute("projects", projects.findAll());
        req.setAttribute("people", people.findAll());
        req.getRequestDispatcher("/WEB-INF/jsp/task-form.jsp").forward(req, resp);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String idParam = req.getParameter("id");
        String title = trim(req.getParameter("title"));
        String projectIdParam = req.getParameter("projectId");

        // The title must be present (mirrors NOT NULL on task.title).
        if (title.isEmpty()) {
            fail(req, resp, "Title is required");
            return;
        }
        // The referenced project must exist; checked here as well as by the FK.
        if (projectIdParam == null || projectIdParam.isEmpty() || !projects.exists(Long.parseLong(projectIdParam))) {
            fail(req, resp, "A task must belong to an existing project");
            return;
        }

        Task t = new Task();
        t.setTitle(title);
        t.setDescription(req.getParameter("description"));
        t.setPriority(orDefault(req.getParameter("priority"), "MEDIUM"));
        t.setProjectId(Long.parseLong(projectIdParam));
        String assignee = req.getParameter("assigneeId");
        t.setAssigneeId((assignee == null || assignee.isEmpty()) ? null : Long.valueOf(assignee));
        t.setDueDate(req.getParameter("dueDate"));

        long savedId;
        if (idParam == null || idParam.isEmpty()) {
            t.setStatus(TaskStatus.OPEN); // new tasks always start OPEN
            savedId = tasks.create(t);
        } else {
            savedId = Long.parseLong(idParam);
            t.setId(savedId);
            tasks.update(t);
        }
        // Land on the just-saved task's detail page, not back on the list.
        resp.sendRedirect(req.getContextPath() + "/tasks/form?id=" + savedId + "&saved=1");
    }

    private void fail(HttpServletRequest req, HttpServletResponse resp, String msg)
            throws ServletException, IOException {
        req.setAttribute("error", msg);
        req.setAttribute("projects", projects.findAll());
        req.setAttribute("people", people.findAll());
        req.getRequestDispatcher("/WEB-INF/jsp/task-form.jsp").forward(req, resp);
    }

    private static String trim(String s) {
        return s == null ? "" : s.trim();
    }

    private static String orDefault(String s, String def) {
        return (s == null || s.isEmpty()) ? def : s;
    }
}

package com.acme.tracker.dao;

import com.acme.tracker.db.Database;
import com.acme.tracker.model.Task;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

public class TaskDao {

    private static final String BASE =
        "SELECT t.id, t.title, t.description, t.status, t.priority, t.assignee_id, " +
        "       t.project_id, t.due_date, t.updated_at, a.full_name AS assignee_name, p.name AS project_name " +
        "FROM task t " +
        "JOIN project p ON p.id = t.project_id " +
        "LEFT JOIN person a ON a.id = t.assignee_id";

    public List<Task> findAll() {
        return run(BASE + " ORDER BY t.updated_at DESC");
    }

    public Task findById(long id) {
        List<Task> rows = runWith(BASE + " WHERE t.id = ?", id);
        return rows.isEmpty() ? null : rows.get(0);
    }

    public List<Task> findByProject(long projectId) {
        return runWith(BASE + " WHERE t.project_id = ? ORDER BY t.id", projectId);
    }

    /**
     * Finds tasks; the status and assignee filters are optional and the WHERE
     * clause is assembled dynamically. Values are parameterized; only the sort
     * column is concatenated (whitelisted), the classic legacy shortcut.
     */
    public List<Task> search(String status, Long assigneeId, String sort) {
        StringBuilder sql = new StringBuilder(BASE);
        List<Object> params = new ArrayList<>();
        List<String> where = new ArrayList<>();
        if (status != null && !status.isEmpty()) {
            where.add("t.status = ?");
            params.add(status);
        }
        if (assigneeId != null) {
            where.add("t.assignee_id = ?");
            params.add(assigneeId);
        }
        if (!where.isEmpty()) {
            sql.append(" WHERE ").append(String.join(" AND ", where));
        }
        // Whitelist the sort expression to avoid injection via the concatenation.
        sql.append(" ORDER BY ").append(orderClause(sort));

        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(sql.toString())) {
            for (int i = 0; i < params.size(); i++) {
                ps.setObject(i + 1, params.get(i));
            }
            try (ResultSet rs = ps.executeQuery()) {
                List<Task> out = new ArrayList<>();
                while (rs.next()) {
                    out.add(map(rs));
                }
                return out;
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    public long create(Task t) {
        String sql = "INSERT INTO task (title, description, status, priority, assignee_id, project_id, due_date) " +
                     "VALUES (?, ?, ?, ?, ?, ?, ?)";
        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(sql, PreparedStatement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, t.getTitle());
            ps.setString(2, t.getDescription());
            ps.setString(3, t.getStatus());
            ps.setString(4, t.getPriority());
            setNullableLong(ps, 5, t.getAssigneeId());
            ps.setLong(6, t.getProjectId());
            setNullableDate(ps, 7, t.getDueDate());
            ps.executeUpdate();
            try (ResultSet keys = ps.getGeneratedKeys()) {
                keys.next();
                return keys.getLong("id");
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    public void update(Task t) {
        String sql = "UPDATE task SET title = ?, description = ?, priority = ?, assignee_id = ?, due_date = ?, " +
                     "updated_at = CURRENT_TIMESTAMP WHERE id = ?";
        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setString(1, t.getTitle());
            ps.setString(2, t.getDescription());
            ps.setString(3, t.getPriority());
            setNullableLong(ps, 4, t.getAssigneeId());
            setNullableDate(ps, 5, t.getDueDate());
            ps.setLong(6, t.getId());
            ps.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    /** Raw status write. */
    public void updateStatus(long id, String status) {
        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(
                     "UPDATE task SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?")) {
            ps.setString(1, status);
            ps.setLong(2, id);
            ps.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    /** Sets status DONE for many ids in a single UPDATE statement. */
    public int bulkClose(long[] ids) {
        if (ids == null || ids.length == 0) {
            return 0;
        }
        StringBuilder in = new StringBuilder();
        for (int i = 0; i < ids.length; i++) {
            in.append(i == 0 ? "?" : ",?");
        }
        String sql = "UPDATE task SET status = 'DONE', updated_at = CURRENT_TIMESTAMP " +
                     "WHERE status <> 'DONE' AND id IN (" + in + ")";
        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(sql)) {
            for (int i = 0; i < ids.length; i++) {
                ps.setLong(i + 1, ids[i]);
            }
            return ps.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Whitelisted ORDER BY expression. `sort` is a UI token (updated/status/
     * priority/due), never a column name from the request — mapped to a fixed
     * clause here. Default is most-recently-updated first.
     */
    private static String orderClause(String sort) {
        if ("status".equals(sort)) {
            return "t.status, t.updated_at DESC";
        }
        if ("priority".equals(sort)) {
            // Semantic order HIGH > MEDIUM > LOW (not alphabetical).
            return "CASE t.priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END, t.updated_at DESC";
        }
        if ("due".equals(sort) || "due_date".equals(sort)) {
            return "t.due_date, t.updated_at DESC";
        }
        if ("title".equals(sort)) {
            return "t.title, t.id";
        }
        if ("id".equals(sort)) {
            return "t.id";
        }
        return "t.updated_at DESC"; // default, and explicit "updated"
    }

    private static void setNullableLong(PreparedStatement ps, int idx, Long v) throws SQLException {
        if (v == null) {
            ps.setNull(idx, java.sql.Types.BIGINT);
        } else {
            ps.setLong(idx, v);
        }
    }

    private static void setNullableDate(PreparedStatement ps, int idx, String iso) throws SQLException {
        if (iso == null || iso.isEmpty()) {
            ps.setNull(idx, java.sql.Types.DATE);
        } else {
            ps.setDate(idx, java.sql.Date.valueOf(iso));
        }
    }

    private List<Task> run(String sql) {
        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            List<Task> out = new ArrayList<>();
            while (rs.next()) {
                out.add(map(rs));
            }
            return out;
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    private List<Task> runWith(String sql, long arg) {
        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setLong(1, arg);
            try (ResultSet rs = ps.executeQuery()) {
                List<Task> out = new ArrayList<>();
                while (rs.next()) {
                    out.add(map(rs));
                }
                return out;
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    private Task map(ResultSet rs) throws SQLException {
        Task t = new Task();
        t.setId(rs.getLong("id"));
        t.setTitle(rs.getString("title"));
        t.setDescription(rs.getString("description"));
        t.setStatus(rs.getString("status"));
        t.setPriority(rs.getString("priority"));
        long aid = rs.getLong("assignee_id");
        t.setAssigneeId(rs.wasNull() ? null : aid);
        t.setAssigneeName(rs.getString("assignee_name"));
        t.setProjectId(rs.getLong("project_id"));
        t.setProjectName(rs.getString("project_name"));
        java.sql.Date d = rs.getDate("due_date");
        t.setDueDate(d == null ? null : d.toString());
        java.sql.Timestamp u = rs.getTimestamp("updated_at");
        // Trim the fractional seconds: "2026-07-17 14:23:05.123" -> "2026-07-17 14:23:05"
        t.setUpdatedAt(u == null ? null : u.toString().substring(0, 19));
        return t;
    }
}

package com.acme.tracker.dao;

import com.acme.tracker.db.Database;
import com.acme.tracker.model.Project;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

public class ProjectDao {

    private static final String BASE =
        "SELECT p.id, p.name, p.description, p.state, p.owner_id, o.full_name AS owner_name " +
        "FROM project p JOIN person o ON o.id = p.owner_id";

    public List<Project> findAll() {
        List<Project> out = new ArrayList<>();
        try (Connection c = Database.getConnection();
             PreparedStatement ps = c.prepareStatement(BASE + " ORDER BY p.name");
